def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        def _wrapper(*args, **kwargs):
            now = timer()
            for key, (value, timestamp) in list(cache.items()):
                if now - timestamp > ttl:
                    del cache[key]
            try:
                return cache[args]
            except KeyError:
                value = func(*args, **kwargs)
                cache[args] = (value, now)
                return value
        return _wrapper
    return wrapper

def mru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def wrapped(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result
        return wrapped
    return wrapper

def lru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def inner(*args, **kwargs):
            key = args + tuple(kwargs.items())
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.pop(next(iter(cache)))
            return result
        return inner
    return wrapper

def lfu_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        use_count = {}
        current_size = 0

        def wrapped(*args, **kwargs):
            nonlocal current_size
            key = args if typed else repr(args)
            if key in cache:
                use_count[key] += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if current_size < maxsize:
                    cache[key] = result
                    use_count[key] = 1
                    current_size += 1
                else:
                    for k, v in sorted(use_count.items(), key=lambda x: x[1]):
                        if v == 1:
                            del cache[k]
                            del use_count[k]
                            current_size -= 1
                            break
                return result
        return wrapped
    return wrapper

