def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for root, dirs, files in os.walk(self.storage_root):
        for name in files:
            file_path = os.path.join(root, name)
            if not self.is_valid_file(file_path):
                continue
            num_objects += 1
            if validate_objects:
                if not self.is_valid_object(file_path):
                    if show_warnings:
                        print(f"WARNING: Invalid object found: {file_path}")
                    continue
            if check_digests:
                if not self.is_valid_digest(file_path):
                    if show_warnings:
                        print(f"WARNING: Invalid digest found: {file_path}")
                    continue
            good_objects += 1
    return num_objects, good_objects

