def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.content
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be one of 'left', 'right', or 'middle'")
    if len(field_names) != 2:
        raise ValueError("field_names must have 2 elements")
    if scale is not None and not isinstance(scale, (int, float)):
        raise ValueError("scale must be a number or None")

    graph = Graph(field_names)
    for bin_ in hist.bins:
        x = bin_.left if get_coordinate == "left" else bin_.right
        y = make_value(bin_)
        graph.add_point(x, y)

    if scale is not None:
        graph.scale = scale
    return graph

def verifyClass(iface, candidate, tentative=False):
    if not inspect.isclass(candidate):
        return False
    if not issubclass(candidate, iface):
        return False
    if tentative:
        return True
    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = [base.__class__ for base in bases]
    if not metaclasses:
        return type
    else:
        metaclass = metaclasses[0]
        for cls in metaclasses[1:]:
            if not issubclass(metaclass, cls):
                raise TypeError("metaclass conflict: %s" % metaclasses)
        return metaclass

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    min_count = min(self.values())
    for key, count in self.items():
        if count == min_count:
            break
    else:
        raise KeyError("popitem(): dictionary has no least frequently used item")
    value = self.pop(key)
    return key, value

def popitem(self):
    if not self._data:
        raise KeyError("popitem(): dictionary is empty")
    key = None
    for k, _ in self._data.items():
        if key is None or self._data[k] < self._data[key]:
            key = k
    value = self._data.pop(key)
    return (key, value)

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

