def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary containing the resolved argument values.
    """
    # Get the argument spec from the function
    argspec = inspect.getfullargspec(self.function)

    # Get the default values from the spec
    spec_defaults = argspec.defaults
    if spec_defaults is None:
        spec_defaults = []

    # Get the default values from the function annotations
    annotation_defaults = {}
    for arg in argspec.args:
        if arg in self.function.__annotations__:
            annotation_defaults[arg] = self.function.__annotations__[arg]

    # Merge the default values from the spec and annotations
    defaults = {**spec_defaults, **annotation_defaults}

    return defaults

